(() => {
 const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>(Number(v)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const modules={overview:'Visão geral',products:'Produtos',stock:'Estoque',coupons:'Cupons',banners:'Banners e parceiros',customers:'Clientes',orders:'Pedidos',settings:'Configurações'};
 const initial={products:[{id:'demo-whey',name:'Whey Protein (exemplo)',brand:'Demonstrativo',category:'Proteínas',sku:'DEMO-001',flavor:'Chocolate',size:'900 g',price:12990,image:'',active:true}],stock:[],coupons:[{id:'demo-coupon',code:'ATLETIC10',percent:10,minimum:0,expires:'',active:true}],banners:[]};
 let data;try{data=JSON.parse(localStorage.getItem('atletic.admin.demo.v1'))}catch{};
 if(!data||!['products','stock','coupons','banners'].every(k=>Array.isArray(data[k])))data=structuredClone(initial);
 let page='overview',editing=null;
 const fields={products:[['name','Nome do produto','text',true],['brand','Marca','text',true],['category','Categoria','select',true,['Proteínas','Creatinas','Pré-treinos','Vitaminas','Acessórios']],['sku','SKU / código interno','text',true],['flavor','Sabor','text'],['size','Peso ou tamanho','text'],['price','Preço (R$)','money',true],['image','URL da foto (HTTPS)','url'],['active','Ativo','checkbox']],stock:[['product','Produto','product',true],['lot','Lote','text',true],['expires','Validade','date'],['delta','Entrada (+) ou saída (−)','integer',true],['reason','Motivo da movimentação','text',true]],coupons:[['code','Código do cupom','text',true],['percent','Desconto (%)','percent',true],['minimum','Compra mínima (R$)','money',true],['expires','Validade','date'],['active','Ativo','checkbox']],banners:[['title','Título do anúncio','text',true],['partner','Nome do parceiro','text',true],['image','Imagem desktop (HTTPS)','url'],['mobile','Imagem celular (HTTPS)','url'],['whatsapp','WhatsApp com DDI e DDD','tel',true],['message','Mensagem inicial','textarea'],['active','Ativo','checkbox']]};
 function notify(t){$('#adminStatus').textContent=t;$('#adminStatus').classList.add('visible');setTimeout(()=>$('#adminStatus').classList.remove('visible'),3500)}
 function persist(){localStorage.setItem('atletic.admin.demo.v1',JSON.stringify(data))}
 function stock(id){return data.stock.filter(x=>x.product===id).reduce((s,x)=>s+Number(x.delta),0)}
 function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#pageTitle').textContent=modules[page];const content=$('#adminContent');
 if(page==='overview'){content.innerHTML=`<div class="admin-cards"><div class="admin-card"><span>Produtos de teste</span><strong>${data.products.length}</strong></div><div class="admin-card"><span>Unidades em estoque de teste</span><strong>${data.stock.reduce((s,x)=>s+Number(x.delta),0)}</strong></div><div class="admin-card"><span>Cupons de teste ativos</span><strong>${data.coupons.filter(x=>x.active).length}</strong></div><div class="admin-card"><span>Pedidos reais</span><strong>—</strong></div></div><h2>Preparação da operação</h2><ul><li>Cadastre produtos e suas variações para experimentar o fluxo.</li><li>Registre entradas e saídas por lote com justificativa.</li><li>Organize cupons e anúncios de parceiros.</li><li>Conexão ao banco e autenticação aguardando projeto Supabase disponível.</li></ul>`;return}
 if(page==='customers'||page==='orders'){content.innerHTML=`<div class="empty-panel"><h2>${page==='customers'?'Cadastro seguro de clientes':'Gestão de pedidos'}</h2><p>${page==='customers'?'Acesso, endereços e histórico serão habilitados após conectar o banco e a autenticação.':'Pedidos, pagamentos, reserva de estoque e entregas serão habilitados com o banco e o checkout.'}</p><p>Este módulo não recebe nem armazena dados reais na demonstração.</p></div>`;return}
 if(page==='settings'){content.innerHTML='<div class="empty-panel"><h2>Integrações</h2><p>GitHub → Vercel: deploy automático.</p><p>Supabase: aguardando projeto disponível; limite de projetos gratuitos atingido.</p><p>Pagamentos: provedor ainda não escolhido.</p><p>Estes cadastros são locais e não alteram o catálogo público.</p><button id="resetDemo" class="button">Restaurar dados de exemplo</button></div>';$('#resetDemo').onclick=()=>{if(confirm('Apagar somente os cadastros de demonstração deste navegador?')){data=structuredClone(initial);persist();render();notify('Demonstração restaurada')}};return}
 content.innerHTML=`<div class="admin-toolbar"><input id="tableSearch" type="search" placeholder="Pesquisar ${modules[page].toLowerCase()}" aria-label="Pesquisar registros"><button id="newRecord" class="button">+ ${page==='stock'?'Registrar movimento':'Novo cadastro'}</button></div><div id="records"></div>`;$('#newRecord').onclick=()=>openEditor();$('#tableSearch').oninput=renderRows;renderRows();
 }
 function renderRows(){const term=$('#tableSearch').value.toLowerCase();const rows=data[page].filter(x=>JSON.stringify(x).toLowerCase().includes(term));const names={products:['Produto / marca','SKU','Preço','Situação','Ações'],stock:['Produto','Lote / validade','Movimento','Motivo','Saldo do produto'],coupons:['Código','Desconto','Compra mínima','Situação','Ações'],banners:['Parceiro','Anúncio','WhatsApp','Situação','Ações']};$('#records').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr>${names[page].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>{let cols;if(page==='products')cols=[`${esc(r.name)}<br><small>${esc(r.brand)}</small>`,esc(r.sku),money(r.price)];if(page==='coupons')cols=[esc(r.code),esc(r.percent)+'%',money(r.minimum)];if(page==='banners')cols=[esc(r.partner),esc(r.title),esc(r.whatsapp)];if(page==='stock')cols=[esc(data.products.find(p=>p.id===r.product)?.name||'Produto removido'),esc(r.lot)+' / '+esc(r.expires||'Sem validade'),(r.delta>0?'+':'')+r.delta,esc(r.reason),stock(r.product)];else cols.push(`<span class="badge">${r.active?'Ativo':'Inativo'}</span>`,`<button data-edit="${esc(r.id)}">Editar</button><button data-delete="${esc(r.id)}">Excluir</button>`);return '<tr>'+cols.map(c=>`<td>${c}</td>`).join('')+'</tr>'}).join('')}</tbody></table></div>`:'<div class="empty-panel">Nenhum registro encontrado.</div>'}
 function openEditor(id){editing=id||null;const r=data[page].find(x=>x.id===id)||{};$('#editTitle').textContent=page==='stock'?'Movimentar estoque':(id?'Editar':'Novo')+' cadastro';$('#formError').textContent='';$('#fields').innerHTML=fields[page].map(([key,label,type,required,options])=>{const value=type==='money'?(Number(r[key]||0)/100).toFixed(2):r[key]??'';let input;if(type==='checkbox')input=`<input name="${key}" type="checkbox" ${r[key]?'checked':''}>`;else if(type==='textarea')input=`<textarea name="${key}" maxlength="1000">${esc(value)}</textarea>`;else if(type==='select'||type==='product'){const choices=type==='product'?data.products.map(p=>[p.id,p.name]):options.map(o=>[o,o]);input=`<select name="${key}" required>${choices.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`}else input=`<input name="${key}" type="${['money','integer','percent'].includes(type)?'number':type}" ${required?'required':''} ${type==='money'?'min="0" max="1000000" step="0.01"':type==='percent'?'min="1" max="100" step="1"':type==='integer'?'min="-1000000" max="1000000" step="1"':''} value="${esc(value)}" maxlength="250">`;return `<label>${label}${input}</label>`}).join('');$('#editor').showModal()}
 $('#editForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),record={id:editing||crypto.randomUUID()};try{fields[page].forEach(([key,label,type])=>{record[key]=type==='checkbox'?fd.has(key):type==='money'?Math.round(Number(fd.get(key))*100):['integer','percent'].includes(type)?Number(fd.get(key)):String(fd.get(key)||'').trim();if(type==='url'&&record[key]&&!/^https:\/\//i.test(record[key]))throw Error('Use uma URL HTTPS para a imagem.');});if(page==='products'&&data.products.some(x=>x.id!==record.id&&x.sku.toLowerCase()===record.sku.toLowerCase()))throw Error('Já existe um produto com esse SKU.');if(page==='coupons'){record.code=record.code.toUpperCase();if(data.coupons.some(x=>x.id!==record.id&&x.code===record.code))throw Error('Já existe esse cupom.');}if(page==='banners'){record.whatsapp=record.whatsapp.replace(/\D/g,'');if(!/^[1-9]\d{9,14}$/.test(record.whatsapp))throw Error('Informe DDI, DDD e número válido.');}if(page==='stock'){if(!data.products.some(x=>x.id===record.product))throw Error('Cadastre um produto primeiro.');if(!Number.isInteger(record.delta)||record.delta===0)throw Error('Informe quantidade inteira diferente de zero.');const balance=data.stock.filter(x=>x.product===record.product&&x.lot===record.lot).reduce((s,x)=>s+x.delta,0);if(balance+record.delta<0)throw Error('Saldo insuficiente neste lote.');record.created_at=new Date().toISOString();}const before=structuredClone(data);const index=data[page].findIndex(x=>x.id===record.id);if(index>=0)data[page][index]=record;else data[page].push(record);try{persist()}catch(err){data=before;throw Error('Não foi possível salvar no navegador. Verifique o armazenamento.')}$('#editor').close();render();notify('Cadastro salvo somente na demonstração local.')}catch(err){$('#formError').textContent=err.message}};
 $('#closeEditor').onclick=()=>$('#editor').close();document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;render()}const edit=e.target.closest('[data-edit]');if(edit)openEditor(edit.dataset.edit);const del=e.target.closest('[data-delete]');if(del){if(page==='products'&&data.stock.some(x=>x.product===del.dataset.delete)){notify('Produto possui movimentações. Desative-o em vez de excluir.');return}if(confirm('Excluir este registro de demonstração?')){data[page]=data[page].filter(x=>x.id!==del.dataset.delete);persist();render()}}});
 $('#adminNav').innerHTML=Object.entries(modules).map(([id,label])=>`<button data-page="${id}">${label}</button>`).join('');$('#adminTheme').onclick=()=>document.body.classList.toggle('dark');render();
})();
